# Keeps the CSV the page builds for "Download CSV" and stops it reaching Chrome's
# download manager, which crashed the browser a few seconds after each download on
# this machine (Crashpad dumps 2026-09-29). Only the page's own export blob is read.
CAPTURE_JS = r"""
() => {
  if (window.__tpHook) { window.__tpBlobs = []; return; }
  window.__tpHook = true; window.__tpBlobs = [];
  const make = URL.createObjectURL.bind(URL);
  URL.createObjectURL = (obj) => { if (obj instanceof Blob) window.__tpBlobs.push(obj); return make(obj); };
  const isExport = (a) => a && a.hasAttribute && a.hasAttribute('download') && (a.href || '').startsWith('blob:');
  const click = HTMLAnchorElement.prototype.click;
  HTMLAnchorElement.prototype.click = function () { if (isExport(this)) return; return click.apply(this, arguments); };
  document.addEventListener('click', (e) => { const a = e.target.closest && e.target.closest('a'); if (isExport(a)) e.preventDefault(); }, true);
}
"""


def download_csv(page, dest):
    tag(page)
    page.evaluate(CAPTURE_JS)
    more = page.locator("[data-tp=more]")
    if more.count() == 0:
        more = page.get_by_role("button", name=re.compile("more options", re.I))
    if more.count() == 0:
        raise PullError("More options button not found (run --probe)")
    more.last.click()
    time.sleep(0.8)
    item = page.get_by_role("menuitem", name=re.compile("download csv", re.I))
    if item.count() == 0:
        item = page.get_by_text(re.compile(r"^\s*Download CSV\s*$", re.I))
    item.first.click()
    deadline = time.time() + 60
    while time.time() < deadline:
        # Raw bytes (base64), not blob.text(), which would drop the UTF-8 BOM the export carries.
        b64 = page.evaluate("""async () => {
            if (!window.__tpBlobs.length) return null;
            const bytes = new Uint8Array(await window.__tpBlobs[window.__tpBlobs.length - 1].arrayBuffer());
            let s = ''; for (let i = 0; i < bytes.length; i += 0x8000) s += String.fromCharCode(...bytes.subarray(i, i + 0x8000));
            return btoa(s);
        }""")
        if b64 is not None:
            Path(dest).write_bytes(base64.b64decode(b64))
            page.keyboard.press("Escape")  # the menu stays open when the download is held back
            time.sleep(0.5)
            return
        time.sleep(0.5)
    raise PullError("Download CSV produced no file within 60 s")


def check_file(path, tab_key, group, previous_bytes):
    raw = Path(path).read_bytes()
    if previous_bytes is not None and raw == previous_bytes:
        raise PullError("file is identical to the previous download (table did not refresh)")
    rows = list(csv.DictReader(io.StringIO(raw.decode("utf-8-sig"))))
    if not rows:
        raise PullError("CSV has no rows (table empty when downloaded)")
    is_adv = "Player Impact" in rows[0]
    if is_adv != (tab_key == "advanced"):
        raise PullError(f"expected {tab_key} but header says {'advanced' if is_adv else 'traits'}")
    codes = Counter(r.get("Pos.", "") for r in rows)
    expected = GROUPS[group][1]
    share = sum(n for c, n in codes.items() if c in expected) / len(rows)
    if share < 0.9:
        raise PullError(f"only {share:.0%} of rows carry {group} codes: {codes.most_common(4)}")
    snaps = [int(r["Snaps"]) for r in rows if (r.get("Snaps") or "").isdigit()]
    return {"rows": len(rows), "teams": len({r.get('Team') for r in rows}),
            "max_snaps": max(snaps) if snaps else None, "pos_codes": dict(codes.most_common(5))}, raw


def launch(profile):
    from playwright.sync_api import sync_playwright
    pw = sync_playwright().start()
    # Own download folder: with the default (the user's Downloads) Chrome crashed
    # mid-download on this machine (Crashpad dumps name Downloads\desktop.ini).
    downloads = Path(profile).parent / "downloads"
    downloads.mkdir(parents=True, exist_ok=True)
    ctx = pw.chromium.launch_persistent_context(
        str(profile), channel="chrome", headless=False, accept_downloads=True,
        downloads_path=str(downloads), viewport={"width": 1400, "height": 950})
    page = ctx.pages[0] if ctx.pages else ctx.new_page()
    return pw, ctx, page


def main():
    ap = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    ap.add_argument("--season", type=int)
    ap.add_argument("--scope", default="FBS", help='scope option(s) as named in Telemetry, comma-separated: "FBS", "FCS,Group of Six"')
    ap.add_argument("--tag", help="scope tag in file names (default from --scope; 2025 used fcs-g6)")
    ap.add_argument("--out", help="folder for the CSVs (created; existing files are never overwritten)")
    ap.add_argument("--groups", nargs="*", default=list(GROUPS), choices=list(GROUPS))
    ap.add_argument("--tabs", nargs="*", default=["traits", "advanced"], choices=list(TABS))
    ap.add_argument("--profile", default=str(DEFAULT_PROFILE))
    ap.add_argument("--login", action="store_true", help="open Telemetry to log in once, then exit")
    ap.add_argument("--probe", action="store_true", help="print the page's controls and exit")
    args = ap.parse_args()

    profile = Path(args.profile)
    profile.mkdir(parents=True, exist_ok=True)
    pw, ctx, page = launch(profile)
    try:
        page.goto(URL.format(tab="player-traits"), wait_until="domcontentloaded", timeout=60000)
        settle(page, 4)
        if args.login:
            print("Log in to Telemetry in the Chrome window that just opened (you type the password).",
                  "Waiting up to 10 minutes for the leaderboard to appear...", flush=True)
            deadline = time.time() + 600
            while time.time() < deadline:
                try:
                    if "leaderboard" not in page.url:
                        time.sleep(3)
                        continue
                    if tag(page).get("group") and not page.locator("input[type=password]").count():
                        time.sleep(3)  # let the session cookies settle before closing
                        print("Logged in. Saved to the tool profile; later runs reuse it.")
                        return
                except Exception:
                    pass  # page navigating during login
                time.sleep(3)
            sys.exit("Timed out waiting for login.")
        print("Telemetry opened; checking login...", flush=True)
        ok = logged_in(page)
        if args.probe:
            print("logged in:", ok)
            print(json.dumps(page.evaluate(PROBE_JS), indent=2))
            print(json.dumps(tag(page), indent=2))
            return
        if not ok:
            sys.exit("Not logged in (or the leaderboard did not load). Run with --login first.")
        if not (args.season and args.out):
            sys.exit("--season and --out are required")

        out = Path(args.out)
        out.mkdir(parents=True, exist_ok=True)
        scopes = [x.strip() for x in args.scope.split(",") if x.strip()]
        scope_tag = args.tag or "-".join(re.sub(r"[^a-z0-9]+", "-", x.lower()).strip("-") for x in scopes)
        manifest = {"season": args.season, "scope": args.scope, "started": time.strftime("%Y-%m-%d %H:%M"),
                    "files": {}, "failed": {}}
        for tab_key in args.tabs:
            slug, label = TABS[tab_key]
            page.goto(URL.format(tab=slug), wait_until="domcontentloaded", timeout=60000)  # resets filters
            settle(page, 4)
            set_scope(page, scopes)
            set_select(page, "season", str(args.season))
            previous = None
            for group in args.groups:
                name = f"{args.season}_{scope_tag}_{GROUPS[group][0]}_{slug}.csv"
                dest = out / name
                if dest.exists():
                    print(f"skip  {name} (exists)")
                    continue
                for attempt in (1, 2):
                    try:
                        set_select(page, "group", f"{group} {label}")
                        state = tag(page)
                        if state.get("season") != str(args.season) or set(state.get("scopes", [])) != set(scopes):
                            raise PullError(f"filters drifted: {state}")
                        tmp = out / (name + ".part")
                        download_csv(page, tmp)
                        info, previous = check_file(tmp, tab_key, group, previous)
                        tmp.rename(dest)
                        manifest["files"][name] = info
                        print(f"ok    {name}: {info['rows']} rows, {info['teams']} teams, top snaps {info['max_snaps']}")
                        break
                    except Exception as e:
                        for p in out.glob(name + ".part"):
                            p.unlink()
                        if attempt == 2:
                            manifest["failed"][name] = str(e)
                            print(f"FAIL  {name}: {e}")
                        else:
                            print(f"retry {name}: {e}")
                            page.keyboard.press("Escape")
                            settle(page)
        manifest["finished"] = time.strftime("%Y-%m-%d %H:%M")
        mpath = out / f"manifest_{args.season}_{scope_tag}.json"
        if mpath.exists():  # a rerun that skipped existing files keeps their entries
            earlier = json.loads(mpath.read_text(encoding="utf-8"))
            manifest["files"] = {**earlier.get("files", {}), **manifest["files"]}
            manifest["started"] = earlier.get("started", manifest["started"])
            for name in manifest["files"]:
                manifest["failed"].pop(name, None)
        mpath.write_text(json.dumps(manifest, indent=2), encoding="utf-8")
        teams = {i["teams"] for i in manifest["files"].values()}
        print(f"\n{len(manifest['files'])} files, {len(manifest['failed'])} failed. Teams per file: {sorted(teams)}. "
              f"Manifest: {mpath}")
        if manifest["failed"]:
            sys.exit(1)
    finally:
        ctx.close()
        pw.stop()


if __name__ == "__main__":
    main()
